// D1 tables (docs/backend.md, D1 schema). camelCase properties, snake_case columns.
// Better Auth tables are in auth-schema.ts (generated by `npx auth@latest generate`, don't edit by hand).
import { index, integer, primaryKey, real, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { users } from "./auth-schema";

export * from "./auth-schema";

/**
 * Subsidized OpenRouter key, one per user (docs/backend.md, AI subsidy). OpenRouter
 * returns the key text only once, so it is stored encrypted for a second device.
 */
export const aiKeys = sqliteTable("ai_keys", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  keyHash: text("key_hash").notNull(),
  keyEnc: text("key_enc").notNull(),
  limitUsd: real("limit_usd").notNull(),
  expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
  createdAt: integer("created_at", { mode: "timestamp_ms" }).notNull(),
});

/** Beta invite code: single-use, consumed at sign-up. */
export const inviteCodes = sqliteTable("invite_codes", {
  code: text("code").primaryKey(),
  usedBy: text("used_by").references(() => users.id, { onDelete: "set null" }),
  usedAt: integer("used_at", { mode: "timestamp_ms" }),
  // Nullable: SQLite's ADD COLUMN can't default to "now", and codes made before the column have
  // no known date. Drizzle inserts fill it; raw SQL inserts (scripts) set it themselves.
  createdAt: integer("created_at", { mode: "timestamp_ms" }).$defaultFn(() => new Date()),
});

/**
 * Per-user usage (docs/backend.md, D1 schema): `bytes` = R2, checked
 * against `USER_STORAGE_BYTES` on every upload. `seq` = sync order.
 * `syncBytes` = size of sync records in D1 (key length + JSON data), checked
 * against `SYNC_STORAGE_BYTES`. `syncRows` = sync rows written on UTC day
 * `syncDay` (days since epoch), checked against `SYNC_DAILY_WRITES`. `usageRows` = usage rows
 * written on UTC day `usageDay`, checked against `USAGE_DAILY_ROWS`.
 */
export const userStorage = sqliteTable("user_storage", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  bytes: integer("bytes").notNull().default(0),
  seq: integer("seq").notNull().default(0),
  syncBytes: integer("sync_bytes").notNull().default(0),
  syncDay: integer("sync_day").notNull().default(0),
  syncRows: integer("sync_rows").notNull().default(0),
  usageDay: integer("usage_day").notNull().default(0),
  usageRows: integer("usage_rows").notNull().default(0),
});

/**
 * Sync data per row (docs/sync-protocol.md, Records and keys). `data` = the Dart fields
 * as JSON (camelCase), null for a tombstone. `seq` = per-user order for pull.
 * `schema_version` = Drift schema version of the sending app; an older version
 * must not overwrite a newer record.
 */
export const records = sqliteTable(
  "records",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    key: text("key").notNull(),
    data: text("data"),
    updatedAt: integer("updated_at").notNull(),
    deleted: integer("deleted", { mode: "boolean" }).notNull().default(false),
    schemaVersion: integer("schema_version").notNull(),
    seq: integer("seq").notNull(),
  },
  // Index (user_id, seq): pull reads only rows after the cursor, not all of the user's records.
  (t) => [
    primaryKey({ columns: [t.userId, t.kind, t.key] }),
    index("records_user_seq").on(t.userId, t.seq),
  ],
);

/**
 * Daily usage rollup sent by the app (docs/backend.md, Usage analytics): one row per local
 * `day` (YYYY-MM-DD) × feature × model × book × key source. Empty strings mean "none" in key
 * columns. A resend replaces the row, so counts are never added twice.
 */
export const usageDaily = sqliteTable(
  "usage_daily",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    day: text("day").notNull(),
    feature: text("feature").notNull(),
    model: text("model").notNull(),
    bookKey: text("book_key").notNull(),
    bookTitle: text("book_title"),
    keySource: text("key_source").notNull(),
    calls: integer("calls").notNull(),
    failed: integer("failed").notNull(),
    promptTokens: integer("prompt_tokens").notNull(),
    completionTokens: integer("completion_tokens").notNull(),
    costUsd: real("cost_usd"),
    readingSeconds: integer("reading_seconds").notNull(),
    updatedAt: integer("updated_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day, t.feature, t.model, t.bookKey, t.keySource] })],
);
